<?php
namespace App\Http\Controllers\Tenant;
use App\Http\Controllers\Controller;use App\Models\MediaAsset;use App\Services\ImageSanitizer;use App\Tenancy\TenantContext;use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;use Illuminate\Support\Str;
class MediaController extends Controller{
 public function index(TenantContext $ctx){$tenant=$ctx->requireTenant();return view('tenant.manage.media',['tenant'=>$tenant,'assets'=>MediaAsset::where('tenant_id',$tenant->id)->latest()->paginate(48)]);}
 public function store(Request $r,TenantContext $ctx,ImageSanitizer $sanitizer){$tenant=$ctx->requireTenant();$d=$r->validate(['file'=>'required|file|max:15360|mimes:jpg,jpeg,png,webp,gif','visibility'=>'required|in:public,tenant,private','alt_text'=>'nullable|string|max:255']);$file=$d['file'];$disk=$d['visibility']==='public'?'public':'local';$name=Str::uuid().'.'.strtolower($file->getClientOriginalExtension());$path=$file->storeAs('tenant/'.$tenant->id.'/media',$name,$disk);abort_unless($path,500,'Upload failed.');$absolute=Storage::disk($disk)->path($path);$stripped=$sanitizer->sanitize($absolute,(string)$file->getMimeType());$asset=MediaAsset::create(['tenant_id'=>$tenant->id,'uploaded_by'=>$r->user()->id,'disk'=>$disk,'path'=>$path,'original_name'=>$file->getClientOriginalName(),'mime_type'=>$file->getMimeType(),'size'=>filesize($absolute)?:0,'alt_text'=>$d['alt_text']??null,'visibility'=>$d['visibility'],'sha256'=>hash_file('sha256',$absolute),'metadata_stripped'=>$stripped]);return back()->with('status','Media uploaded.');}
 public function show(Request $r,TenantContext $ctx,MediaAsset $asset){$tenant=$ctx->requireTenant();abort_unless($asset->tenant_id===$tenant->id,404);if($asset->visibility==='private')abort_unless($r->user()&&$tenant->users()->where('users.id',$r->user()->id)->exists(),403);return Storage::disk($asset->disk)->response($asset->path,$asset->original_name,['Cache-Control'=>$asset->visibility==='public'?'public,max-age=86400':'private,no-store']);}
 public function destroy(TenantContext $ctx,MediaAsset $asset){$tenant=$ctx->requireTenant();abort_unless($asset->tenant_id===$tenant->id,404);Storage::disk($asset->disk)->delete($asset->path);$asset->delete();return back()->with('status','Media deleted.');}
}